{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "Diphenhydramine, a close diphenylmethyl tertiary-amine analogue with the highest transfer score (0.9736), has absolute oral bioavailability of 69% in humans, directly supporting F >= 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Trimipramine, a lipophilic basic tricyclic amine (transfer 0.968), showed absolute oral bioavailability of 41.4% in subjects, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Pethidine/meperidine, a basic phenylpiperidine ester (transfer 0.9618), had absolute oral bioavailability of 57% in healthy volunteers, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Dapoxetine, a lipophilic tertiary amine with aromatic groups (transfer 0.9591), had absolute oral bioavailability of 42% in healthy volunteers, supporting high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Milnacipran, an amide-containing basic drug (transfer 0.9569), had absolute oral bioavailability of 85 ± 3% in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Fenspiride, a phenethyl piperidine-like drug (transfer 0.9501), had absolute oral bioavailability of 90% in healthy volunteers, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Perindoprilat (S-9780) after oral perindopril showed 19 ± 7% bioavailability in young healthy subjects, but this is an active-metabolite endpoint for a polar dicarboxylic acid prodrug, not the parent lipophilic amide; it is less direct and does not outweigh the consistent supportive evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer human absolute bioavailability analogues—diphenhydramine, trimipramine, pethidine, dapoxetine, milnacipran, and fenspiride—all show F >= 20%, with most values well above the threshold. The only sub-20% record is for a polar active metabolite (perindoprilat) and is endpoint-mismatched. The query's lipophilic basic amide structure is consistent with these high-bioavailability analogues, so F >= 20% is strongly supported.",
  "evidence_gaps": [
    "No direct human absolute bioavailability data exist for the query molecule itself.",
    "The only borderline low record is for an active metabolite rather than the parent drug, limiting its directness.",
    "No specific information on first-pass metabolism, efflux transport, or solubility for the query is available, though the analogue evidence is consistent."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

